def max_value_on_paths(N, grid_values):
    dp = [[0] * N for _ in range(N)]

    for x, y, value in grid_values:
        x -= 1
        y -= 1
        dp[y][x] = value

    for i in range(1, N):
        for j in range(N):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

    return dp[N - 1][N - 1]

