def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        raise ValueError("n and m must be positive integers")

    # Initialize a 2D array to store the results of subproblems
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: If n = 1 or m = 1, there is only one way to pass the ball (starting student)
    for i in range(1, m + 1):
        dp[1][i] = 1

    for i in range(2, n + 1):
        for j in range(1, m + 1):
            # If the ball has returned to the starting student, there is only one way to pass it
            if j == 1:
                dp[i][j] = 1
            else:
                # Each student can pass the ball to the left or right neighbor
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]

    return dp[n][m]

